#[inline]
unsafe extern "C-unwind" fn init_ref_map_pair(
    mut cpi: *mut AV1_COMP,
    mut ref_frame_map_pairs: *mut RefFrameMapPair,
) {
    if (*(*cpi).ppi).gf_group.update_type[(*cpi).gf_frame_index as usize]
        as core::ffi::c_int == KF_UPDATE as core::ffi::c_int
    {
        memset(
            ref_frame_map_pairs as *mut core::ffi::c_void,
            -(1 as core::ffi::c_int),
            (::core::mem::size_of::<RefFrameMapPair>() as size_t)
                .wrapping_mul(REF_FRAMES as core::ffi::c_int as size_t),
        );
        return;
    }
    memset(
        ref_frame_map_pairs as *mut core::ffi::c_void,
        0 as core::ffi::c_int,
        (::core::mem::size_of::<RefFrameMapPair>() as size_t)
            .wrapping_mul(REF_FRAMES as core::ffi::c_int as size_t),
    );
    let mut map_idx: core::ffi::c_int = 0 as core::ffi::c_int;
    while map_idx < REF_FRAMES as core::ffi::c_int {
        let buf: *const RefCntBuffer = (*cpi).common.ref_frame_map[map_idx as usize];
        if !((*ref_frame_map_pairs.offset(map_idx as isize)).disp_order
            == -(1 as core::ffi::c_int))
        {
            if buf.is_null() {
                (*ref_frame_map_pairs.offset(map_idx as isize)).disp_order = -(1
                    as core::ffi::c_int);
                (*ref_frame_map_pairs.offset(map_idx as isize)).pyr_level = -(1
                    as core::ffi::c_int);
            } else {
                if (*buf).ref_count > 1 as core::ffi::c_int {
                    let mut idx2: core::ffi::c_int = map_idx + 1 as core::ffi::c_int;
                    while idx2 < REF_FRAMES as core::ffi::c_int {
                        let buf2: *const RefCntBuffer = (*cpi)
                            .common
                            .ref_frame_map[idx2 as usize];
                        if buf2 == buf {
                            (*ref_frame_map_pairs.offset(idx2 as isize)).disp_order = -(1
                                as core::ffi::c_int);
                            (*ref_frame_map_pairs.offset(idx2 as isize)).pyr_level = -(1
                                as core::ffi::c_int);
                        }
                        idx2 += 1;
                    }
                }
                (*ref_frame_map_pairs.offset(map_idx as isize)).disp_order = (*buf)
                    .display_order_hint as core::ffi::c_int;
                (*ref_frame_map_pairs.offset(map_idx as isize)).pyr_level = (*buf)
                    .pyramid_level as core::ffi::c_int;
            }
        }
        map_idx += 1;
    }
}
