unsafe extern "C-unwind" fn set_size_independent_vars(mut cpi: *mut AV1_COMP) {
    let mut i: core::ffi::c_int = 0;
    let cm: *mut AV1_COMMON = &raw mut (*cpi).common;
    let features: *mut FeatureFlags = &raw mut (*cm).features;
    i = LAST_FRAME as core::ffi::c_int;
    while i <= ALTREF_FRAME as core::ffi::c_int {
        (*cm).global_motion[i as usize] = default_warp_params;
        i += 1;
    }
    (*cpi).gm_info.search_done = 0 as core::ffi::c_int != 0;
    av1_set_speed_features_framesize_independent(cpi as *mut AV1_COMP, (*cpi).speed);
    av1_set_rd_speed_thresholds(cpi as *mut AV1_COMP);
    (*features).interp_filter = SWITCHABLE;
    (*features).switchable_motion_mode = is_switchable_motion_mode_allowed(
        (*features).allow_warped_motion,
        (*cpi).oxcf.motion_mode_cfg.enable_obmc,
    );
}
