unsafe extern "C-unwind" fn restore_all_coding_context(mut cpi: *mut AV1_COMP) {
    restore_extra_coding_context(cpi);
    if frame_is_intra_only(&raw mut (*cpi).common) == 0 {
        release_scaled_references(cpi);
    }
}
