unsafe extern "C-unwind" fn refresh_reference_frames(mut cpi: *mut AV1_COMP) {
    let cm: *mut AV1_COMMON = &raw mut (*cpi).common;
    let mut num_ref_buffers: core::ffi::c_int = REF_FRAMES as core::ffi::c_int;
    if reduce_num_ref_buffers(cpi) != 0 {
        let refresh_all_bufs: core::ffi::c_int = ((*(*cpi).ppi)
            .gf_group
            .refbuf_state[(*cpi).gf_frame_index as usize] as core::ffi::c_int
            == REFBUF_RESET as core::ffi::c_int || frame_is_sframe(cm) != 0)
            as core::ffi::c_int;
        if !(!((*cm).current_frame.refresh_frame_flags >> 7 as core::ffi::c_int
            & 1 as core::ffi::c_int == 1 as core::ffi::c_int) || refresh_all_bufs != 0)
            as core::ffi::c_int as core::ffi::c_long != 0
        {
            crate::platform::assertion(
                (::core::mem::transmute::<
                    [u8; 25],
                    [core::ffi::c_char; 25],
                >(*b"refresh_reference_frames\0"))
                    .as_ptr(),
                b"encoder_utils.h\0" as *const u8 as *const core::ffi::c_char,
                997 as core::ffi::c_int,
                b"IMPLIES(((cm->current_frame.refresh_frame_flags >> 7) & 1) == 1, refresh_all_bufs)\0"
                    as *const u8 as *const core::ffi::c_char,
            );
        } else {};
        num_ref_buffers -= 1;
    }
    let mut ref_frame: core::ffi::c_int = 0 as core::ffi::c_int;
    while ref_frame < num_ref_buffers {
        if (*cm).current_frame.refresh_frame_flags >> ref_frame & 1 as core::ffi::c_int
            == 1 as core::ffi::c_int
        {
            assign_frame_buffer_p(
                &raw mut *((*cm).ref_frame_map).as_mut_ptr().offset(ref_frame as isize),
                (*cm).cur_frame,
            );
        }
        ref_frame += 1;
    }
}
