unsafe extern "C-unwind" fn alloc_context_buffers_ext(
    mut cm: *mut AV1_COMMON,
    mut mbmi_ext_info: *mut MBMIExtFrameBufferInfo,
) {
    let mi_params: *const CommonModeInfoParams = &raw mut (*cm).mi_params;
    let mi_alloc_size_1d: core::ffi::c_int = mi_size_wide[(*mi_params).mi_alloc_bsize
        as usize] as core::ffi::c_int;
    let mi_alloc_rows: core::ffi::c_int = ((*mi_params).mi_rows + mi_alloc_size_1d
        - 1 as core::ffi::c_int) / mi_alloc_size_1d;
    let mi_alloc_cols: core::ffi::c_int = ((*mi_params).mi_cols + mi_alloc_size_1d
        - 1 as core::ffi::c_int) / mi_alloc_size_1d;
    let new_ext_mi_size: core::ffi::c_int = mi_alloc_rows * mi_alloc_cols;
    if new_ext_mi_size > (*mbmi_ext_info).alloc_size {
        dealloc_context_buffers_ext(mbmi_ext_info);
        if ((*(*cm).error).setjmp == 0) as core::ffi::c_int as core::ffi::c_long != 0 {
            crate::platform::assertion(
                (::core::mem::transmute::<
                    [u8; 26],
                    [core::ffi::c_char; 26],
                >(*b"alloc_context_buffers_ext\0"))
                    .as_ptr(),
                b"encoder_alloc.h\0" as *const u8 as *const core::ffi::c_char,
                51 as core::ffi::c_int,
                b"((cm)->error)->setjmp\0" as *const u8 as *const core::ffi::c_char,
            );
        } else {};
        (*mbmi_ext_info).frame_base = aom_malloc(
            (new_ext_mi_size as size_t)
                .wrapping_mul(::core::mem::size_of::<MB_MODE_INFO_EXT_FRAME>() as size_t),
        ) as *mut MB_MODE_INFO_EXT_FRAME;
        if ((*mbmi_ext_info).frame_base).is_null() {
            aom_internal_error(
                (*cm).error,
                AOM_CODEC_MEM_ERROR,
                b"Failed to allocate mbmi_ext_info->frame_base at %s:%d\0" as *const u8
                    as *const core::ffi::c_char,
                b"upstream/aom/av1/encoder/encoder_alloc.h\0" as *const u8
                    as *const core::ffi::c_char,
                51 as core::ffi::c_int,
            );
        }
        (*mbmi_ext_info).alloc_size = new_ext_mi_size;
    }
    (*mbmi_ext_info).stride = mi_alloc_cols;
}
