    (*seq_params).transfer_characteristics = (*color_cfg).transfer_characteristics;
    (*seq_params).matrix_coefficients = (*color_cfg).matrix_coefficients;
    (*seq_params).monochrome = (*oxcf).tool_cfg.enable_monochrome as uint8_t;
