    (*seq_params).timing_info.equal_picture_interval = (*dec_model_cfg)
        .timing_info
        .equal_picture_interval;
    (*seq_params).timing_info.num_ticks_per_picture = (*dec_model_cfg)
        .timing_info
        .num_ticks_per_picture;
    (*seq_params).display_model_info_present_flag = (*dec_model_cfg)
        .display_model_info_present_flag as uint8_t;
