unsafe extern "C-unwind" fn update_motion_stat(cpi: *mut AV1_COMP) {
    let cm: *mut AV1_COMMON = &raw mut (*cpi).common;
    let mi_params: *const CommonModeInfoParams = &raw mut (*cm).mi_params;
    let rc: *mut RATE_CONTROL = &raw mut (*cpi).rc;
    let svc: *mut SVC = &raw mut (*cpi).svc;
    let avg_cnt_zeromv: core::ffi::c_int = 100 as core::ffi::c_int * (*cpi).rc.cnt_zeromv
        / ((*mi_params).mi_rows * (*mi_params).mi_cols);
    if (*(*cpi).ppi).use_svc == 0
        || (*(*cpi).ppi).use_svc != 0
            && (*((*cpi).svc.layer_context)
                .offset((*cpi).svc.temporal_layer_id as isize))
                .is_key_frame == 0
            && (*cpi).svc.spatial_layer_id
                == (*cpi).svc.number_spatial_layers - 1 as core::ffi::c_int
    {
        (*rc).avg_frame_low_motion = if (*rc).avg_frame_low_motion
            == 0 as core::ffi::c_int
        {
            avg_cnt_zeromv
        } else {
            (3 as core::ffi::c_int * (*rc).avg_frame_low_motion + avg_cnt_zeromv)
                / 4 as core::ffi::c_int
        };
        if (*(*cpi).ppi).use_svc != 0
            && (*svc).spatial_layer_id
                == (*svc).number_spatial_layers - 1 as core::ffi::c_int
        {
            let mut i: core::ffi::c_int = 0 as core::ffi::c_int;
            while i < (*svc).number_spatial_layers - 1 as core::ffi::c_int {
                let layer: core::ffi::c_int = i * (*svc).number_temporal_layers
                    + (*svc).temporal_layer_id;
                let lc: *mut LAYER_CONTEXT = &raw mut *((*svc).layer_context)
                    .offset(layer as isize) as *mut LAYER_CONTEXT;
                let lrc: *mut RATE_CONTROL = &raw mut (*lc).rc;
                (*lrc).avg_frame_low_motion = (*rc).avg_frame_low_motion;
                i += 1;
            }
        }
    }
}
