unsafe extern "C-unwind" fn selective_disable_cdf_rtc(
    mut cpi: *const AV1_COMP,
) -> core::ffi::c_int {
    let cm: *const AV1_COMMON = &(*cpi).common;
    let rc: *const RATE_CONTROL = &(*cpi).rc;
    if (*cpi).svc.number_spatial_layers == 1 as core::ffi::c_int
        && (*cpi).svc.number_temporal_layers == 1 as core::ffi::c_int
    {
        if frame_is_intra_only(cm) != 0 || is_frame_resize_pending(cpi) != 0
            || (*rc).high_source_sad != 0
            || (*rc).frames_since_key < 30 as core::ffi::c_int
            || (*cpi).oxcf.q_cfg.aq_mode as core::ffi::c_int
                == CYCLIC_REFRESH_AQ as core::ffi::c_int
                && (*(*cpi).cyclic_refresh).counter_encode_maxq_scene_change
                    < 30 as core::ffi::c_int
            || (*cpi).frames_since_last_update > 8 as core::ffi::c_int
                && (*cpi).rc.frame_source_sad > 0 as uint64_t
        {
            return 0 as core::ffi::c_int
        } else {
            return 1 as core::ffi::c_int
        }
    } else if (*cpi).svc.number_temporal_layers > 1 as core::ffi::c_int {
        return ((*cpi).svc.temporal_layer_id
            == (*cpi).svc.number_temporal_layers - 1 as core::ffi::c_int)
            as core::ffi::c_int
    }
    return 1 as core::ffi::c_int;
}
unsafe extern "C-unwind" fn subtract_stats(
    mut section: *mut FIRSTPASS_STATS,
    mut frame: *const FIRSTPASS_STATS,
) {
    (*section).frame -= (*frame).frame;
    (*section).weight -= (*frame).weight;
    (*section).intra_error -= (*frame).intra_error;
    (*section).frame_avg_wavelet_energy -= (*frame).frame_avg_wavelet_energy;
    (*section).coded_error -= (*frame).coded_error;
    (*section).sr_coded_error -= (*frame).sr_coded_error;
    (*section).lt_coded_error -= (*frame).lt_coded_error;
    (*section).pcnt_inter -= (*frame).pcnt_inter;
    (*section).pcnt_motion -= (*frame).pcnt_motion;
    (*section).pcnt_second_ref -= (*frame).pcnt_second_ref;
    (*section).pcnt_neutral -= (*frame).pcnt_neutral;
    (*section).intra_skip_pct -= (*frame).intra_skip_pct;
    (*section).inactive_zone_rows -= (*frame).inactive_zone_rows;
    (*section).inactive_zone_cols -= (*frame).inactive_zone_cols;
    (*section).MVr -= (*frame).MVr;
    (*section).mvr_abs -= (*frame).mvr_abs;
    (*section).MVc -= (*frame).MVc;
    (*section).mvc_abs -= (*frame).mvc_abs;
    (*section).MVrv -= (*frame).MVrv;
    (*section).MVcv -= (*frame).MVcv;
    (*section).mv_in_out_count -= (*frame).mv_in_out_count;
    (*section).new_mv_count -= (*frame).new_mv_count;
    (*section).count -= (*frame).count;
    (*section).duration -= (*frame).duration;
}
unsafe extern "C-unwind" fn calculate_frame_avg_haar_energy(mut cpi: *mut AV1_COMP) {
    let twopass: *mut TWO_PASS = &raw mut (*(*cpi).ppi).twopass;
    let total_stats: *const FIRSTPASS_STATS = (*(*twopass).stats_buf_ctx).total_stats;
    if is_one_pass_rt_params(cpi) != 0
        || (*cpi).oxcf.q_cfg.deltaq_mode as core::ffi::c_int
            != DELTA_Q_PERCEPTUAL as core::ffi::c_int
        || is_fp_wavelet_energy_invalid(total_stats) == 0 as core::ffi::c_int
    {
        return;
    }
    let num_mbs: core::ffi::c_int = if (*cpi).oxcf.resize_cfg.resize_mode
        as core::ffi::c_int != RESIZE_NONE as core::ffi::c_int
    {
        (*cpi).initial_mbs
    } else {
        (*cpi).common.mi_params.MBs
    };
    let unfiltered_source: *const YV12_BUFFER_CONFIG = (*cpi).unfiltered_source;
    let src: *const uint8_t = (*unfiltered_source)
        .c2rust_unnamed_4
        .c2rust_unnamed
        .y_buffer;
    let hbd: core::ffi::c_int = (*unfiltered_source).flags & YV12_FLAG_HIGHBITDEPTH;
    let stride: core::ffi::c_int = (*unfiltered_source)
        .c2rust_unnamed_3
        .c2rust_unnamed
        .y_stride;
    let fp_block_size: BLOCK_SIZE = get_fp_block_size((*cpi).is_screen_content_type)
        as BLOCK_SIZE;
    let fp_block_size_width: core::ffi::c_int = block_size_wide[fp_block_size as usize]
        as core::ffi::c_int;
    let fp_block_size_height: core::ffi::c_int = block_size_high[fp_block_size as usize]
        as core::ffi::c_int;
    let num_unit_cols: core::ffi::c_int = get_num_blocks(
        (*unfiltered_source).c2rust_unnamed_1.c2rust_unnamed.y_crop_width,
        fp_block_size_width,
    ) as core::ffi::c_int;
    let num_unit_rows: core::ffi::c_int = get_num_blocks(
        (*unfiltered_source).c2rust_unnamed_2.c2rust_unnamed.y_crop_height,
        fp_block_size_height,
    ) as core::ffi::c_int;
    let num_8x8_cols: core::ffi::c_int = num_unit_cols
        * (fp_block_size_width / 8 as core::ffi::c_int);
    let num_8x8_rows: core::ffi::c_int = num_unit_rows
        * (fp_block_size_height / 8 as core::ffi::c_int);
    let mut frame_avg_wavelet_energy: int64_t = av1_haar_ac_sad_mxn_uint8_input(
        src,
        stride,
        hbd,
        num_8x8_rows,
        num_8x8_cols,
    );
    (*cpi).twopass_frame.frame_avg_haar_energy = log1p(
        frame_avg_wavelet_energy as core::ffi::c_double / num_mbs as core::ffi::c_double,
    );
}
